mapper.select:
SELECT id, household_id, owner_user_id, name, type, balance, created_at
FROM accounts
WHERE id = #{id}

SELECT id, household_id, owner_user_id, name, type, balance, created_at
FROM accounts
WHERE household_id = #{householdId}
  AND owner_user_id = #{ownerUserId}
ORDER BY id

mapper.update:
UPDATE accounts
SET name = #{name}, type = #{type}
WHERE id = #{id}

UPDATE accounts
SET balance = #{balance}
WHERE id = #{id}
